def validate(tool_name, args):
    schema = TOOL_SCHEMAS.get(tool_name)
    if schema is None:
        return False, {"error": "unknown_tool", "tool": tool_name}
    for field in schema["required"]:
        if field not in args:
            return False, {"error": "missing_field", "field": field}
    return True, {}

